// Shared data loading for the archive. Base data is the pre-built static
// JSON generated by scripts/build_data.py. On top of that, we merge a live
// delta from GET /api/posts-feed (posts added/edited/deleted through the
// deployed site's Add Post form, stored in Netlify Blobs — see
// netlify/functions/). That endpoint doesn't exist when just browsing the
// static files locally (e.g. `python3 -m http.server`), so any failure to
// reach it is swallowed and we fall back to the static data as-is.

const Archive = (() => {
  let mainPosts = null;
  let unnumberedPosts = null;
  let mainById = null;
  let feedPromise = null;

  function loadFeed() {
    if (!feedPromise) {
      feedPromise = fetch("/api/posts-feed")
        .then((res) => (res.ok ? res.json() : null))
        .catch(() => null)
        .then((feed) => feed || {
          numbered: { overrides: {}, deleted: [] },
          unnumbered: { overrides: {}, deleted: [] },
        });
    }
    return feedPromise;
  }

  function applyOverlay(basePosts, { overrides, deleted }) {
    const deletedSet = new Set(deleted);
    const merged = basePosts
      .filter((p) => !deletedSet.has(p.post_id))
      .map((p) => (Object.prototype.hasOwnProperty.call(overrides, String(p.post_id)) ? overrides[String(p.post_id)] : p));

    const knownIds = new Set(merged.map((p) => p.post_id));
    for (const [id, post] of Object.entries(overrides)) {
      const key = typeof basePosts[0]?.post_id === "number" ? Number(id) : id;
      if (!knownIds.has(key) && !deletedSet.has(key)) {
        merged.push(post);
      }
    }
    return merged;
  }

  async function loadMain() {
    if (mainPosts) return mainPosts;
    const res = await fetch("data/website-posts.json");
    if (!res.ok) throw new Error("Failed to load website-posts.json");
    const basePosts = await res.json();
    const feed = await loadFeed();
    mainPosts = applyOverlay(basePosts, feed.numbered).sort((a, b) => a.post_id - b.post_id);
    mainById = new Map(mainPosts.map((p) => [p.post_id, p]));
    return mainPosts;
  }

  async function loadUnnumbered() {
    if (unnumberedPosts) return unnumberedPosts;
    const res = await fetch("data/website-posts-unnumbered.json");
    if (!res.ok) throw new Error("Failed to load website-posts-unnumbered.json");
    const basePosts = await res.json();
    const feed = await loadFeed();
    unnumberedPosts = applyOverlay(basePosts, feed.unnumbered);
    return unnumberedPosts;
  }

  // Media added through the live Add Post form is stored as a Netlify Blob,
  // not a static file, so it's tagged with a "blob-media/" prefix and needs
  // to go through the streaming function instead of a direct relative path.
  function mediaUrl(path) {
    return path.startsWith("blob-media/") ? `/api/media/${path.slice("blob-media/".length)}` : path;
  }

  async function getById(postId) {
    await loadMain();
    return mainById.get(postId) || null;
  }

  async function getUnnumberedById(id) {
    await loadUnnumbered();
    return unnumberedPosts.find((p) => p.post_id === id) || null;
  }

  async function neighbors(postId) {
    await loadMain();
    const idx = mainPosts.findIndex((p) => p.post_id === postId);
    if (idx === -1) return { prev: null, next: null };
    return {
      prev: idx > 0 ? mainPosts[idx - 1] : null,
      next: idx < mainPosts.length - 1 ? mainPosts[idx + 1] : null,
    };
  }

  function textPreview(text, len = 140) {
    if (!text) return "";
    const clean = text.replace(/\s+/g, " ").trim();
    return clean.length > len ? clean.slice(0, len).trim() + "…" : clean;
  }

  function formatDate(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleDateString(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  }

  // Strips any line that contains a URL (e.g. "LINK - https://...",
  // "VIDEO PREVIEW - https://...") out of the displayed caption - those
  // links are already surfaced as their own "Watch / Open" / "Link N"
  // buttons (see post.links), so repeating the raw URL in the text is
  // redundant.
  function stripLinkLines(text) {
    if (!text) return "";
    return text
      .split("\n")
      .filter((line) => !/https?:\/\/\S+/.test(line))
      .join("\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

  function escapeHtml(str) {
    return (str || "").replace(/[&<>"']/g, (c) => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;",
    }[c]));
  }

  return {
    loadMain,
    loadUnnumbered,
    getById,
    getUnnumberedById,
    neighbors,
    textPreview,
    formatDate,
    escapeHtml,
    mediaUrl,
    stripLinkLines,
  };
})();
